def build_agent(sandbox):
    # Define beam parameters for structural rigidity and buoyancy
    beam_width = 1.5  # Longer in the direction of travel
    beam_height = 0.5  # Narrower to reduce bending moments
    beam_density = 35.0  # Sufficient mass for control, not too heavy for buoyancy

    # Centered at y=0.25 to sit on the ground (bottom at y=0.0) and float in water (top at y=0.75)
    y_center = 0.25
    beam_centers_x = [3.0, 5.0, 7.0]  # Spaced within the build zone

    bodies = []
    for x in beam_centers_x:
        b = sandbox.add_beam(x, y_center, beam_width, beam_height, angle=0, density=beam_density)
        sandbox.set_material_properties(b, restitution=0.05)
        bodies.append(b)

    # Connect adjacent beams with rigid joints
    for i in range(len(bodies) - 1):
        anchor_x = (beam_centers_x[i] + beam_centers_x[i + 1]) / 2
        sandbox.add_joint(bodies[i], bodies[i + 1], (anchor_x, y_center), type='rigid')

    return bodies[1]  # Return the middle beam for control


